/bin/bash -lc "mkdir -p out
cat > out/decisions.json <<'EOF'
[
  {
    \"id\": \"api-403\",
    \"decision\": \"recommend\",
    \"skill_id\": \"http-error-triage\",
    \"reason\": \"Matches the need to distinguish credential failures, endpoint changes, and CDN/WAF blocks before rotating credentials.\"
  },
  {
    \"id\": \"uptime-covered\",
    \"decision\": \"covered\",
    \"skill_id\": null,
    \"reason\": \"The already loaded domain-uptime-monitor provides content checks and alerts only on domain state changes.\"
  },
  {
    \"id\": \"translate-basic\",
    \"decision\": \"unnecessary\",
    \"skill_id\": null,
    \"reason\": \"A basic German translation can be handled directly without an additional Skill.\"
  },
  {
    \"id\": \"private-mail\",
    \"decision\": \"clarify\",
    \"skill_id\": null,
    \"reason\": \"An authenticated Gmail connection or mailbox export is required. Clarify how the user will provide access; a Skill cannot supply it.\"
  },
  {
    \"id\": \"agent-quality\",
    \"decision\": \"recommend\",
    \"skill_id\": \"agent-evals\",
    \"reason\": \"Directly covers repeatable agent evaluations from production failures using deterministic checks, cost, latency, and trace evidence.\"
  },
  {
    \"id\": \"logo-keyword-trap\",
    \"decision\": \"no_match\",
    \"skill_id\": null,
    \"reason\": \"No catalog Skill covers logo design. The security audit checklist reviews technical security, not visual identity.\"
  }
]
EOF
python - <<'PY'
import json
from pathlib import Path
items = json.loads(Path('out/decisions.json').read_text())
assert len(items) == 6
for item in items:
    assert set(item) == {'id', 'decision', 'skill_id', 'reason'}
    assert item['decision'] in {'recommend', 'covered', 'unnecessary', 'clarify', 'no_match'}
    assert len(item['reason']) < 180
    if item['decision'] == 'recommend':
        assert (Path('catalog') / item['skill_id']).is_dir()
    else:
        assert item['skill_id'] is None
print('Validated 6 decisions.')
PY"

